    {f : ι → Space n → ℝ} {g : Space n → ℝ} {x : Space n}
    (hf : ∀ j, ConvexOn ℝ univ (f j)) (hd : ∀ j, DifferentiableAt ℝ (f j) x)
    (hg : DifferentiableAt ℝ g x)
    (hlim : ∀ y, Tendsto (fun j => f j y) l (𝓝 (g y))) (w : Space n) :
    Tendsto (fun j => fderiv ℝ (f j) x w) l (𝓝 (fderiv ℝ g x w))

lemma convex_gradient_limit {n : ℕ} {ι : Type uι} {l : Filter ι}
    {f : ι → Space n → ℝ} {g : Space n → ℝ} {x : Space n}
    (hf : ∀ j, ConvexOn ℝ univ (f j)) (hd : ∀ j, DifferentiableAt ℝ (f j) x)
    (hg : DifferentiableAt ℝ g x)
    (hlim : ∀ y, Tendsto (fun j => f j y) l (𝓝 (g y))) :
    Tendsto (fun j => ∇ (f j) x) l (𝓝 (∇ g x))

lemma normSmooth_gradient_tendsto {n : ℕ} (g : Seminorm ℝ (Space n)) {x : Space n}
    (hx : DifferentiableAt ℝ (g : Space n → ℝ) x) :
    Tendsto (fun j => ∇ (normSmooth g (shrinkingBump n j)) x) atTop (𝓝 (∇ (g : Space n → ℝ) x))

lemma boundedMeasure_integrable_continuous {n : ℕ} {μ : Measure (Space n)} [IsFiniteMeasure μ]
    (hb : ∃ B : ℝ, 0 ≤ B ∧ ∀ᵐ x ∂μ, ‖x‖ ≤ B) {f : Space n → ℝ}
    (hf : Continuous f) : Integrable f μ

lemma gaugeMeasure_bounded {n : ℕ} {K : Set (Space n)}
    (hc : Convex ℝ K) (h0 : K ∈ 𝓝 (0 : Space n)) :
    ∃ B : ℝ, 0 ≤ B ∧ ∀ᵐ x ∂gaugeProjectionMeasure K, ‖x‖ ≤ B

lemma gaugeMeasure_finite {n : ℕ} [NeZero n] {K : Set (Space n)}
    (hK : IsCompact K) (hc : Convex ℝ K) (h0 : K ∈ 𝓝 (0 : Space n)) :
    IsFiniteMeasure (gaugeProjectionMeasure K)

lemma gaugeMeasure_integral {n : ℕ} {K : Set (Space n)}
    (hc : Convex ℝ K) (h0 : K ∈ 𝓝 (0 : Space n)) {f : Space n → ℝ}
    (hf : StronglyMeasurable f) :
    ∫ x,f x ∂gaugeProjectionMeasure K =
      mean (fun u : Sphere n => (gauge K (u : Space n))⁻¹^n*f (∇ (gauge K) (u : Space n)))

lemma gaugeMeasure_mass {n : ℕ} [NeZero n] {K : Set (Space n)}
    (hK : IsCompact K) (hc : Convex ℝ K) (h0 : K ∈ 𝓝 (0 : Space n)) :
    (gaugeProjectionMeasure K).real univ=volume.real K/kappa n

lemma gaugeMeasure_probability {n : ℕ} [NeZero n] {K : Set (Space n)}
    (hK : IsCompact K) (hc : Convex ℝ K) (h0 : K ∈ 𝓝 (0 : Space n))
    (hv : volume.real K=kappa n) : IsProbabilityMeasure (gaugeProjectionMeasure K)

lemma gaugeMeasure_self {n : ℕ} [NeZero n] {K : Set (Space n)}
    (hK : IsCompact K) (hc : Convex ℝ K) (h0 : K ∈ 𝓝 (0 : Space n)) :
    supportFunctional (gaugeProjectionMeasure K) K=volume.real K/kappa n

lemma gaugeMeasure_shadow {n : ℕ} [NeZero n] {K : Set (Space n)}
    (hK : IsCompact K) (hc : Convex ℝ K) (h0 : K ∈ 𝓝 (0 : Space n)) (u : Sphere n) :
    2*shadowVolume K u=n*kappa n*∫ x,|⟪x,(u : Space n)⟫| ∂gaugeProjectionMeasure K

lemma gauge_pos_sphere {n : ℕ} [NeZero n] {K : Set (Space n)}
    (hK : IsCompact K) (hc : Convex ℝ K) (h0 : K ∈ 𝓝 (0 : Space n))
    (u : Sphere n) : 0 < gauge K (u : Space n)

lemma signedPair_add_left {n : ℕ} [NeZero n] {F G J : Sphere n → Space n}
    (hF : Continuous F) (hG : Continuous G) (hJ : Continuous J) :
    signedPair (fun u => F u+G u) J = signedPair F J+signedPair G J

lemma signedPair_add_right {n : ℕ} [NeZero n] {F G J : Sphere n → Space n}
    (hF : Continuous F) (hG : Continuous G) (hJ : Continuous J) :
    signedPair F (fun u => G u+J u) = signedPair F G+signedPair F J

lemma sphereGradient_product_scalar_inner {n : ℕ} {f : Space n → ℝ}
    (hf : ContDiff ℝ 1 f) {ρ ρ' : ℝ → ℝ}
    (hρ : ∀ t, HasDerivAt ρ (ρ' t) t) (v x w : Space n) :
    ⟪sphereGradient (fun y => f y*ρ ⟪v,y⟫) x,w⟫ =
      ρ ⟪v,x⟫*⟪sphereGradient f x,w⟫+
      f x*ρ' ⟪v,x⟫*(⟪v,w⟫-⟪v,x⟫*⟪x,w⟫)

lemma cosine_harmonic_odd {n d : ℕ} [NeZero n] {p : MvPolynomial (Fin n) ℝ}
    (hp : p.IsHomogeneous d) (hd : Odd d) (u : Sphere n) :
    cosine (fun x => polynomialFunction p x) u = 0

lemma cosine_selfadj {n : ℕ} [NeZero n] {f g : Sphere n → ℝ}
    (hf : Continuous f) (hg : Continuous g) :
    mean (fun u => f u*cosine g u) = mean (fun u => cosine f u*g u)

lemma cosine_sub_smul {n : ℕ} [NeZero n] {f g : Sphere n → ℝ}
    (hf : Continuous f) (hg : Continuous g) (a : ℝ) (u : Sphere n) :
    cosine (fun x => f x-a*g x) u = cosine f u-a*cosine g u

lemma gradient_pow {n : ℕ} {f : Space n → ℝ} {x : Space n}
    (hf : DifferentiableAt ℝ f x) (k : ℕ) :
    ∇ (fun y => f y^k) x = ((k : ℝ)*f x^(k-1)) • ∇ f x

lemma seminorm_euler {n : ℕ} (g : Seminorm ℝ (Space n)) {x : Space n}
    (hd : DifferentiableAt ℝ (g : Space n → ℝ) x) :
    fderiv ℝ g x x = g x

lemma signedPair_congr_ae {n : ℕ} {F G F' G' : Sphere n → Space n}
    (hF : F =ᵐ[sigma n] F') (hG : G =ᵐ[sigma n] G') :
    signedPair F G = signedPair F' G'

lemma radialExtension_tendsto {n : ℕ} {g : ℕ → Seminorm ℝ (Space n)}
    {f : Sphere n → ℝ} (h : ∀ u : Sphere n,Tendsto (fun i => g i u) atTop (𝓝 (f u)))
    (x : Space n) : Tendsto (fun i => g i x) atTop (𝓝 (radialExtension f x))

lemma functional_smul {n : ℕ} {μ : Measure (Space n)}
    {K : Set (Space n)} (hK : IsCompact K) (hne : K.Nonempty) {a : ℝ} (ha : 0≤a) :
    supportFunctional μ (a • K)=a*supportFunctional μ K

lemma integrable_abs_inner {n : ℕ} {μ : Measure (Space n)}
    (hμ : Integrable (fun x : Space n => ‖x‖) μ) (y : Space n) :
    Integrable (fun x => |⟪x,y⟫|) μ

lemma cosine_le_gauge_functional (g : RelativeGauge V) {μ : MeasureTheory.Measure (Space n)}
    (hμ : MeasureTheory.Integrable (fun x : Space n => ‖x‖) μ) (x : Space n) :
    cosineSeminorm μ hμ (V.starProjection x)≤g x*supportFunctional μ g.body

lemma cylinder_nhds {K : Set (Space n)}
    (hinner : ∃ r : ℝ,0<r ∧ ∀ x∈V,‖x‖≤r → x∈K) :
    V.starProjection ⁻¹' K∈𝓝 (0:Space n)

lemma functional_bound (g : RelativeGauge V) {μ : Measure (Space n)}
    (hμ : Integrable (fun x : Space n => ‖x‖) μ) {c : ℝ} (hc : 0<c)
    (hl : ∀ x,c*‖V.starProjection x‖≤g x) : supportFunctional μ g.body≤c⁻¹*(∫ x,‖x‖ ∂μ)

lemma functional_le_scale (g f : RelativeGauge V) {μ : Measure (Space n)}
    (hμ : Integrable (fun x : Space n => ‖x‖) μ) {a : ℝ} (ha : 0<a)
    (hle : ∀ x,f x≤a*g x) : supportFunctional μ g.body≤a*supportFunctional μ f.body

lemma functional_pos (g : RelativeGauge V) (hV : V≠⊥) {μ : Measure (Space n)}
    (hμ : Integrable (fun x : Space n => ‖x‖) μ)
    (hq : ∀ x∈V,x≠0 → 0<cosineSeminorm μ hμ x) : 0 < supportFunctional μ g.body

lemma normalized_lower (g : RelativeGauge V) {μ : Measure (Space n)}
    (hμ : Integrable (fun x : Space n => ‖x‖) μ) (hn : supportFunctional μ g.body=1) (x : Space n) :
    cosineSeminorm μ hμ (V.starProjection x)≤g x

lemma objective_scale {n : ℕ} [NeZero n] (b : Bool) {g f : Seminorm ℝ (Space n)}
    (hg : g≠0) {a : ℝ} (ha : 0<a) (he : ∀ x,f x=a*g x) :
    objective b f=if b then Real.log a+objective b g else a*objective b g

lemma functional_midpoint (g f : RelativeGauge V) {μ : Measure (Space n)}
    (hμ : Integrable (fun x : Space n => ‖x‖) μ) :
    supportFunctional μ (midpoint g f).body=(supportFunctional μ g.body+supportFunctional μ f.body)/2

lemma homogeneous_integrable {n : ℕ} [NeZero n] {μ : Measure (Space n)}
    (hμ : Integrable (fun x : Space n => ‖x‖) μ) {φ : Space n → ℝ} (hφ : Continuous φ)
    (hh : ∀ a : ℝ,0<a → ∀ x,φ (a • x)=a*φ x) : Integrable φ μ

lemma eventually_pos_det_homotopy {A : E → E →L[ℝ] E} {K : Set E}
    (hK : IsCompact K) (hA : ContinuousOn A K) :
    ∀ᶠ t : ℝ in 𝓝 0, ∀ x∈K, 0<(t • A x+ContinuousLinearMap.id ℝ E).det

lemma nearest_unique {K : Set E} {x p q : E}
    (hp : ∀ z ∈ K, ⟪x-p,z-p⟫ ≤ 0) (hq : ∀ z ∈ K, ⟪x-q,z-q⟫ ≤ 0)
    (hpK : p∈K) (hqK : q∈K) : p=q

theorem fixedPoint_compact_convex {K : Set E} (hne : K.Nonempty)
    (hk : IsCompact K) (hc : Convex ℝ K) {f : E → E}
    (hf : ContinuousOn f K) (hmap : MapsTo f K K) : ∃ x∈K, f x=x

lemma smooth_fixedPoint_ball [FiniteDimensional ℝ E] {f : E → E}
    (hf : ContDiff ℝ 1 f) (hb : ∀ x∈closedBall (0:E) 1, ‖f x‖<1) :
    ∃ x∈closedBall (0:E) 1, f x=x

lemma uniformlyContinuous_ball_extension {f : E → E}
    (hf : ContinuousOn f (closedBall (0:E) 1)) :
    UniformContinuous (fun x => f (ballNearest x))
